findings.codeql_raw_query:
/**
 * @name setuptools package_index os.system command injection
 * @description URL/parameter data flows into os.system inside _download_git/_download_hg
 * @kind path-problem
 * @problem.severity error
 * @id py/setuptools-pkgindex-cmdi
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module CmdInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(DataFlow::ParameterNode p |
      p.getParameter().(Parameter).getName() = "url" and
      source = p
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("os").getMember("system").getACall() and
      sink = call.getArg(0)
    )
  }
}

module CmdInjectionFlow = TaintTracking::Global<CmdInjectionConfig>;
import CmdInjectionFlow::PathGraph

from CmdInjectionFlow::PathNode source, CmdInjectionFlow::PathNode sink
where CmdInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "URL parameter reaches os.system in $@.", sink.getNode(), "command"
